solution.solution.cpp:
#include <cctype>
#include <optional>
#include <string>
#include <vector>

struct Forwarded { std::string cwd; std::vector<std::string> args; };

std::string encodeForward(const Forwarded& f)
{
    std::string out{ f.cwd };
    out += '\0';
    for (const std::string& a : f.args) { out += a; out += '\0'; }
    return out;
}

std::optional<Forwarded> decodeForward(const std::string& text)
{
    if (text.empty() || text.back() != '\0') return std::nullopt;
    std::vector<std::string> parts;
    std::string current;
    for (char c : text)
    {
        if (c == '\0') { parts.push_back(current); current.clear(); }
        else current += c;
    }
    Forwarded f{ parts[0], { parts.begin() + 1, parts.end() } };
    return f;
}

std::string resolvePath(const std::string& cwd, const std::string& path)
{
    const auto absolute = [](const std::string& p) {
        return (p.size() >= 3 && std::isalpha(static_cast<unsigned char>(p[0])) && p[1] == ':' && p[2] == '\\') || p.rfind("\\\\", 0) == 0;
    };
    const std::string full{ absolute(path) ? path : cwd + "\\" + path };
    std::string root;
    std::size_t at{ 0 };
    if (full.rfind("\\\\", 0) == 0)
    {
        const std::size_t serverEnd{ full.find('\\', 2) };
        const std::size_t shareEnd{ serverEnd == std::string::npos ? std::string::npos : full.find('\\', serverEnd + 1) };
        root = full.substr(0, shareEnd);
        at = shareEnd == std::string::npos ? full.size() : shareEnd;
    }
    else { root = full.substr(0, 2); at = 2; }
    std::vector<std::string> parts;
    std::string piece;
    for (std::size_t i{ at }; i <= full.size(); ++i)
    {
        if (i == full.size() || full[i] == '\\')
        {
            if (piece == "..") { if (!parts.empty()) parts.pop_back(); }
            else if (!piece.empty() && piece != ".") parts.push_back(piece);
            piece.clear();
        }
        else piece += full[i];
    }
    if (parts.empty()) return root.size() == 2 ? root + "\\" : root;
    std::string out{ root };
    for (const std::string& p : parts) out += "\\" + p;
    return out;
}

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

std::vector<std::string> filesToOpen(const Forwarded& f)
{
    std::vector<std::string> files;
    for (const std::string& a : f.args)
    {
        if (a.empty() || a[0] == '-' || a[0] == '/') continue;
        const std::string path{ resolvePath(f.cwd, a) };
        bool seen{ false };
        for (const std::string& existing : files) if (lower(existing) == lower(path)) seen = true;
        if (!seen) files.push_back(path);
    }
    return files;
}

unitTests:
using S = std::vector<std::string>;
using namespace std::string_literals;
TEST("encoding round trip") {
    const Forwarded f{ "C:\\Work", { "--new-window", "notes.md" } };
    const std::string wire{ encodeForward(f) };
    CHECK_EQ(wire, "C:\\Work\0--new-window\0notes.md\0"s);
    const auto back{ decodeForward(wire) };
    CHECK(back.has_value());
    if (back) { CHECK_EQ(back->cwd, std::string("C:\\Work")); CHECK_EQ(back->args, (S{ "--new-window", "notes.md" })); }
    CHECK(!decodeForward("").has_value());
    CHECK(!decodeForward("C:\\Work\0x"s).has_value());
    const auto none{ decodeForward("C:\\\0"s) };
    if (none) CHECK(none->args.empty());
    CHECK(none.has_value());
}
TEST("resolving paths") {
    CHECK_EQ(resolvePath("C:\\Work\\docs", "a.md"), std::string("C:\\Work\\docs\\a.md"));
    CHECK_EQ(resolvePath("C:\\Work\\docs", "..\\b.md"), std::string("C:\\Work\\b.md"));
    CHECK_EQ(resolvePath("C:\\Work", ".\\x\\.\\y\\..\\z.txt"), std::string("C:\\Work\\x\\z.txt"));
    CHECK_EQ(resolvePath("C:\\Work", "D:\\other\\c.md"), std::string("D:\\other\\c.md"));
    CHECK_EQ(resolvePath("C:\\Work", "..\\..\\..\\up.md"), std::string("C:\\up.md"));
    CHECK_EQ(resolvePath("C:\\Work", ".."), std::string("C:\\"));
    CHECK_EQ(resolvePath("C:\\Work", "\\\\nas\\share\\..\\..\\x.md"), std::string("\\\\nas\\share\\x.md"));
}
TEST("files to open") {
    const Forwarded f{ "C:\\Work", { "--goto", "/readonly", "a.md", "sub\\..\\A.MD", "b.md", "C:\\Work\\b.md" } };
    CHECK_EQ(filesToOpen(f), (S{ "C:\\Work\\a.md", "C:\\Work\\b.md" }));
}

